-- ----------------------------------------------------------------------------
-- process_calculator_mappings: 43 self-referential rows
-- (process_route = operation = station name, matching Sheet Metal's own
-- live convention), is_active=false (chk_machine_class_required has no
-- exemption for a real machine station with no machine_class yet -- see
-- generator header), canonical_process_id resolved via the taxonomy join
-- ----------------------------------------------------------------------------
INSERT INTO process_calculator_mappings (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, canonical_process_id)
SELECT 'Machining', v.station, v.station, NULL, NULL, false, v.display_order, pt.id
FROM process_taxonomy pt
JOIN (VALUES
($str$2 Axis Bar Feed Lathe with Sub Spindle$str$, 600),
($str$2 Axis Lathe$str$, 601),
($str$3 Axis Bar Feed Lathe with Sub Spindle$str$, 602),
($str$3 Axis Lathe$str$, 603),
($str$3 Axis Mill$str$, 604),
($str$3 Axis Router$str$, 605),
($str$4 Axis Mill$str$, 606),
($str$5 Axis Mill$str$, 607),
($str$5 Axis Router$str$, 608),
($str$Automated Deburr$str$, 609),
($str$Bench Operation$str$, 610),
($str$Bevel Gear Cutting Machine$str$, 611),
($str$Broach$str$, 612),
($str$Cylindrical Grinder$str$, 613),
($str$Deep Bore Machine$str$, 614),
($str$DeMask$str$, 615),
($str$Drill Press$str$, 616),
($str$Etch Cell$str$, 617),
($str$Gun Drill$str$, 618),
($str$Hob Machine$str$, 619),
($str$Inspection$str$, 620),
($str$Internal Grinder$str$, 621),
