($str$Jig Grind$str$, 623),
($str$Manual Deburr$str$, 624),
($str$Mask Cure$str$, 625),
($str$MillTurn$str$, 626),
($str$No Cost Feature$str$, 627),
($str$Perimeter Cut$str$, 628),
($str$Profile Gear Grinder$str$, 629),
($str$Reciprocating Surface Grinder$str$, 630),
($str$Rotary Surface Grinder$str$, 631),
($str$Scribe$str$, 632),
($str$Shaper$str$, 633),
($str$Shaver$str$, 634),
